import { createElement, X, Plus, Minus } from "lucide";
import { cartStyles } from "./shopify-cart-styles.js";

// Public Storefront credentials; never put an Admin or private token here.
export const shopConfig = {
  domain: "other-world-wines.myshopify.com",
  token: "cf4d429617d832e546dc358d2e891be6",
  // Phase 1 display rule; Shopify still controls the actual checkout rate.
  shippingSettings: { amount: "60.00", currencyCode: "GBP" },
};

const cartFields = `id note totalQuantity checkoutUrl cost { subtotalAmount { amount currencyCode } }
  discountAllocations { discountedAmount { amount currencyCode } }
  lines(first: 100) { nodes { id quantity cost { totalAmount { amount currencyCode } }
    merchandise { ... on ProductVariant { id title product { title } image { url altText } } } } }`;
const storageKey = `other-cart:${shopConfig.domain}`;
let cart = null;
let dialog;
let list;
let status;
let count;
let shipping;
let shippingText;
let shippingProgress;
let shippingSettings = null;
let gift;
let noteInput;
let noteStatus;
let noteDirty = false;
let noteTimer;
let checkout;
let busy = false;
let returnFocus;
let operations = Promise.resolve();
let pending = 0;
const quickBuying = new WeakSet();

async function api(query, variables = {}) {
  const response = await fetch(`https://${shopConfig.domain}/api/2026-07/graphql.json`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Shopify-Storefront-Access-Token": shopConfig.token },
    body: JSON.stringify({ query, variables }),
    signal: AbortSignal.timeout(15000),
  });
  if (!response.ok) throw new Error("The shop is unavailable. Please try again.");
  const result = await response.json();
  if (result.errors?.length) throw new Error(result.errors.map((error) => error.message).join(" "));
  return result.data;
}

function storedId() {
  try { return localStorage.getItem(storageKey); } catch { return null; }
}

function saveCart(value) {
  cart = value;
  try {
    if (cart) localStorage.setItem(storageKey, cart.id);
    else localStorage.removeItem(storageKey);
  } catch { /* The cart still works for this visit when storage is blocked. */ }
}

async function refreshCart() {
  const id = cart?.id || storedId();
  if (id) saveCart((await api(`query($id: ID!) { cart(id: $id) { ${cartFields} } }`, { id })).cart);
}

async function mutate(name, declarations, args, variables) {
  const result = (await api(`mutation(${declarations}) { ${name}(${args}) {
    cart { ${cartFields} } userErrors { message } warnings { message }
  } }`, variables))[name];
  if (result.cart) saveCart(result.cart);
  if (result.userErrors.length) throw new Error(result.userErrors.map((error) => error.message).join(" "));
  status.textContent = result.warnings.map((warning) => warning.message).join(" ");
}

function node(tag, text, parent) {
  const element = document.createElement(tag);
  if (text) element.textContent = text;
  parent?.append(element);
  return element;
}

function money(value) {
  return new Intl.NumberFormat("en-GB", { style: "currency", currency: value.currencyCode }).format(Number(value.amount));
}

export function productPriceText(product) {
  if (!product?.priceRange) return "Price unavailable";
  const { minVariantPrice, maxVariantPrice } = product.priceRange;
  const varies = Number(minVariantPrice.amount) !== Number(maxVariantPrice.amount);
  return `${varies ? "From " : ""}${money(minVariantPrice)}`;
}

function productIdFor(element) {
  const owner = element.closest("[data-shopify-product-id], .featured_item[data-id], [data-product-card][data-id], .w-dyn-item[data-id]");
  return owner?.dataset?.shopifyProductId || owner?.dataset?.id;
}

export function productSale(product) {
  const variants = product?.variants;
  if (!variants || variants.nodes.length !== 1 || variants.pageInfo?.hasNextPage) return null;
  const { price, compareAtPrice } = variants.nodes[0];
  if (!compareAtPrice || price.currencyCode !== compareAtPrice.currencyCode) return null;
  const saving = Math.round(Number(compareAtPrice.amount) * 100) - Math.round(Number(price.amount) * 100);
  if (!Number.isFinite(saving) || saving <= 0) return null;
  return { compare: money(compareAtPrice), saving: `Save ${money({ amount: (saving / 100).toFixed(2), currencyCode: price.currencyCode })}` };
}

export async function populateProductPrices(root) {
  const prices = [...root.querySelectorAll("[data-price], [data-compare-price], [data-price-saving]")];
  if (!prices.length) return;
  const bindings = prices.map((element) => {
    const kind = element.hasAttribute("data-compare-price") ? "compare" : element.hasAttribute("data-price-saving") ? "saving" : "price";
    if (kind !== "price") element.style.display = "none";
    element.textContent = "";
    element.setAttribute("aria-busy", "true");
    const value = productIdFor(element);
    let id = null;
    try { id = shopifyId(value, "Product"); } catch (error) { console.warn("[prices]", error.message); }
    return { element, id, kind };
  });
  const ids = [...new Set(bindings.map(({ id }) => id).filter(Boolean))];
  const products = new Map();
  try {
    for (let offset = 0; offset < ids.length; offset += 250) {
      const data = await api(`query($ids: [ID!]!) {
        nodes(ids: $ids) { ... on Product { id priceRange {
          minVariantPrice { amount currencyCode } maxVariantPrice { amount currencyCode }
        } variants(first: 2) { nodes { price { amount currencyCode } compareAtPrice { amount currencyCode } } pageInfo { hasNextPage } } } }
      }`, { ids: ids.slice(offset, offset + 250) });
      for (const product of data.nodes) if (product?.id) products.set(product.id, product);
    }
  } catch (error) {
    console.warn("[prices] Could not load Shopify prices:", error.message);
  } finally {
    for (const { element, id, kind } of bindings) {
      const product = products.get(id);
      if (kind === "price") element.textContent = productPriceText(product);
      else {
        const sale = productSale(product);
        element.textContent = sale?.[kind] || "";
        element.hidden = !sale;
        element.style.display = sale ? (kind === "saving" ? "inline-flex" : "inline-block") : "none";
      }
      element.removeAttribute("aria-busy");
    }
  }
}

export function shippingMessage(progress) {
  if (!progress) return "";
  const remaining = Number(progress.remaining.amount);
  const amount = new Intl.NumberFormat("en-GB", {
    style: "currency", currency: progress.remaining.currencyCode,
    minimumFractionDigits: Number.isInteger(remaining) ? 0 : 2,
  }).format(remaining);
  return remaining > 0 ? `SPEND ${amount} MORE FOR FREE SHIPPING` : "FREE shipping will be applied at checkout";
}

function renderShippingBanner() {
  if (/^capsule\s*02$/i.test(document.body.dataset.page || "")) return;
  const value = cart || (shippingSettings && {
    cost: { subtotalAmount: { amount: "0", currencyCode: shippingSettings.currencyCode } },
  });
  const message = shippingMessage(getShippingProgress(value, shippingSettings));
  document.querySelectorAll(".scrolling_banner.main .ticker_copy").forEach((copy) => {
    copy.hidden = !message;
    if (copy.textContent !== message) copy.textContent = message;
  });
}

export function getShippingProgress(value, settings) {
  const cost = value?.cost.subtotalAmount;
  if (!cost || !settings || cost.currencyCode !== settings.currencyCode) return null;
  const threshold = Number(settings.amount);
  if (!Number.isFinite(threshold) || threshold <= 0) return null;
  const discounts = (value.discountAllocations || []).reduce((sum, allocation) => {
    return sum + (allocation.discountedAmount.currencyCode === cost.currencyCode ? Number(allocation.discountedAmount.amount) : 0);
  }, 0);
  const spend = Math.max(0, Number(cost.amount) - discounts);
  if (!Number.isFinite(spend)) return null;
  return {
    remaining: { amount: Math.max(0, threshold - spend).toFixed(2), currencyCode: cost.currencyCode },
    percent: Math.min(100, spend / threshold * 100),
  };
}

async function refreshShippingSettings() {
  shippingSettings = shopConfig.shippingSettings;
}

function iconButton(icon, label, parent) {
  const button = node("button", "", parent);
  button.type = "button";
  button.setAttribute("aria-label", label);
  button.title = label;
  button.append(createElement(icon, { width: 20, height: 20, "stroke-width": 1.25, "aria-hidden": "true" }));
  return button;
}

function render() {
  renderShippingBanner();
  list.replaceChildren();
  document.querySelectorAll("[data-cart-btn]").forEach((button) => {
    (button.querySelector("div") || button).textContent = `CART (${cart?.totalQuantity || 0})`;
  });
  const lines = (cart?.lines.nodes || []).filter((line) => line.quantity > 0);
  const quantity = cart?.totalQuantity || 0;
  count.textContent = `(${quantity} ${quantity === 1 ? "item" : "items"})`;
  if (!lines.length) node("p", "Your cart is empty.", list).className = "other-cart-empty";
  for (const line of lines) {
    const row = node("article", "", list);
    row.className = "other-cart-line";
    const variant = line.merchandise;
    if (variant.image) {
      const image = node("img", "", row);
      image.src = variant.image.url;
      image.alt = variant.image.altText || variant.product.title;
      image.width = 160;
      image.height = 160;
    } else {
      node("div", "", row).className = "other-cart-image-placeholder";
    }
    const details = node("div", "", row);
    details.className = "other-cart-details";
    node("h3", variant.product.title, details);
    node("p", money(line.cost.totalAmount), details).className = "other-cart-price";
    if (variant.title !== "Default Title") node("p", variant.title, details).className = "other-cart-variant";
    const controls = node("div", "", details);
    controls.className = "other-cart-quantity";
    for (const [icon, quantity, accessible] of [[Minus, line.quantity - 1, "Decrease quantity"], [Plus, line.quantity + 1, "Increase quantity"]]) {
      if (icon === Plus) node("span", String(line.quantity), controls);
      const button = iconButton(icon, `${accessible}: ${variant.product.title}`, controls);
      button.disabled = busy;
      button.onclick = () => run(() => changeQuantity(line.id, quantity));
    }
    const remove = node("button", "Remove", details);
    remove.type = "button";
    remove.className = "other-cart-remove";
    remove.setAttribute("aria-label", `Remove ${variant.product.title}`);
    remove.disabled = busy;
    remove.onclick = () => run(() => changeQuantity(line.id, 0));
  }
  const progress = lines.length ? getShippingProgress(cart, shippingSettings) : null;
  shipping.hidden = !progress;
  if (progress) {
    shippingText.textContent = shippingMessage(progress);
    shippingProgress.value = progress.percent;
    shippingProgress.setAttribute("aria-valuetext", shippingText.textContent);
  }
  gift.hidden = !lines.length;
  if (!noteDirty) noteInput.value = cart?.note || "";
  checkout.textContent = cart?.totalQuantity ? `CHECKOUT \u2022 ${money(cart.cost.subtotalAmount)}` : "CHECKOUT";
  checkout.disabled = busy || !lines.length;
  dialog.setAttribute("aria-busy", String(busy));
}

async function changeQuantity(id, quantity) {
  if (!quantity) return mutate("cartLinesRemove", "$cartId: ID!, $lineIds: [ID!]!", "cartId: $cartId, lineIds: $lineIds", { cartId: cart.id, lineIds: [id] });
  return mutate("cartLinesUpdate", "$cartId: ID!, $lines: [CartLineUpdateInput!]!", "cartId: $cartId, lines: $lines", { cartId: cart.id, lines: [{ id, quantity }] });
}

function run(operation) {
  pending += 1;
  busy = true;
  render();
  operations = operations.then(async () => {
    status.textContent = "";
    try { await operation(); return true; }
    catch (error) { status.textContent = error.message || "Something went wrong. Please try again."; return false; }
    finally { pending -= 1; busy = pending > 0; render(); }
  });
  return operations;
}

async function saveNote() {
  clearTimeout(noteTimer);
  if (!noteDirty || !cart) return;
  const note = noteInput.value;
  noteStatus.textContent = "Saving...";
  try {
    await mutate("cartNoteUpdate", "$cartId: ID!, $note: String!", "cartId: $cartId, note: $note", { cartId: cart.id, note });
    if (noteInput.value === note) {
      noteDirty = false;
      noteStatus.textContent = "Saved";
    }
  } catch (error) {
    noteStatus.textContent = "Not saved. Please try again.";
    throw error;
  }
}

function openCart() {
  if (!dialog.open) {
    returnFocus = document.activeElement;
    dialog.showModal();
  }
}

export function initShopifyCart() {
  if (dialog) { render(); return; }
  const style = node("style", "", document.head);
  style.textContent = cartStyles;
  dialog = node("dialog", "", document.body);
  dialog.className = "other-cart";
  dialog.dataset.lenisPrevent = "";
  dialog.setAttribute("aria-label", "Shopping cart");
  const header = node("header", "", dialog);
  const title = node("div", "", header);
  title.className = "other-cart-title";
  node("h2", "CART", title);
  count = node("span", "", title);
  const close = iconButton(X, "Close cart", header);
  close.className = "other-cart-close";
  close.onclick = () => dialog.close();
  dialog.addEventListener("close", () => returnFocus?.focus?.({ preventScroll: true }));
  const body = node("div", "", dialog);
  body.className = "other-cart-body";
  shipping = node("section", "", body);
  shipping.className = "other-cart-shipping";
  shippingText = node("p", "", shipping);
  shippingText.setAttribute("aria-live", "polite");
  shippingProgress = node("progress", "", shipping);
  shippingProgress.max = 100;
  shippingProgress.setAttribute("aria-label", "Free shipping progress");
  list = node("div", "", body);
  gift = node("details", "", body);
  gift.className = "other-cart-gift";
  const summary = node("summary", "", gift);
  node("span", "Is this a gift? Add a note.", summary);
  summary.append(createElement(Plus, { width: 22, height: 22, "stroke-width": 1.25, "aria-hidden": "true" }));
  const noteLabel = node("label", "Gift message", gift);
  noteLabel.htmlFor = "other-cart-note";
  noteInput = node("textarea", "", gift);
  noteInput.id = "other-cart-note";
  noteInput.rows = 4;
  noteInput.maxLength = 1000;
  noteInput.addEventListener("input", () => {
    noteDirty = true;
    noteStatus.textContent = "Unsaved changes";
    clearTimeout(noteTimer);
    noteTimer = setTimeout(() => run(saveNote), 650);
  });
  const save = node("button", "Save note", gift);
  save.type = "button";
  save.className = "other-cart-save-note";
  save.onclick = () => run(saveNote);
  noteStatus = node("span", "", gift);
  noteStatus.className = "other-cart-note-status";
  noteStatus.setAttribute("role", "status");
  status = node("p", "", body);
  status.className = "other-cart-status";
  status.setAttribute("role", "status");
  const footer = node("footer", "", dialog);
  checkout = node("button", "Checkout", footer);
  checkout.type = "button";
  checkout.className = "other-checkout";
  checkout.onclick = () => run(async () => {
    await saveNote();
    await refreshCart();
    if (!cart?.totalQuantity) throw new Error("Your cart is empty. Please add your product again.");
    window.location.assign(cart.checkoutUrl);
  });
  node("p", "Shipping & taxes calculated at checkout", footer);
  document.addEventListener("click", (event) => {
    const quickBuy = event.target.closest?.("[data-quickbuy], .quick_buy_btn");
    if (quickBuy) {
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return;
      event.preventDefault();
      if (quickBuy.matches(":disabled") || quickBuy.getAttribute("aria-disabled") === "true") return;
      if (!quickBuying.has(quickBuy)) buyFromButton(quickBuy);
      return;
    }
    if (!event.target.closest?.("[data-cart-btn]")) return;
    event.preventDefault();
    openCart();
    run(async () => { await Promise.all([refreshCart(), refreshShippingSettings()]); });
  });
  render();
  run(async () => { await Promise.all([refreshCart(), refreshShippingSettings()]); });
}

function shopifyId(value, type) {
  const id = value?.trim();
  if (!id) return null;
  if (/^\d+$/.test(id)) return `gid://shopify/${type}/${id}`;
  if (new RegExp(`^gid://shopify/${type}/\\d+$`).test(id)) return id;
  throw new Error(`Invalid Shopify ${type} ID on this product.`);
}

export function quickBuyReference(button) {
  const variant = button.closest("[data-shopify-variant-id]")?.dataset.shopifyVariantId;
  if (variant) return { variantId: shopifyId(variant, "ProductVariant") };
  const product = productIdFor(button);
  if (product) return { id: shopifyId(product, "Product") };
  const card = button.closest(".featured_item, [data-product-card], .w-dyn-item");
  const handle = button.closest("[data-shopify-handle]")?.dataset.shopifyHandle?.trim();
  if (handle) return { handle };
  const links = [button, ...(card?.querySelectorAll("a[href]") || [])];
  for (const link of links) {
    const href = link.getAttribute("href");
    if (!href) continue;
    const url = new URL(href, window.location.href);
    const match = url.pathname.match(/^\/products\/([^/]+)\/?$/);
    if (match && url.origin === window.location.origin) return { handle: decodeURIComponent(match[1]) };
  }
  throw new Error("This product needs a Shopify ID or product link before it can be added.");
}

async function resolveVariant(reference) {
  if (reference.variantId) {
    const data = await api(`query($id: ID!) { node(id: $id) {
      ... on ProductVariant { id availableForSale }
    } }`, { id: reference.variantId });
    if (!data.node?.availableForSale) throw new Error("This product option is unavailable.");
    return data.node.id;
  }
  const data = await api(`query($id: ID, $handle: String) { product(id: $id, handle: $handle) {
    title variants(first: 2) { nodes { id availableForSale } pageInfo { hasNextPage } }
  } }`, reference);
  if (!data.product) throw new Error("This product is not available in the shop.");
  const variants = data.product.variants;
  if (variants.nodes.length !== 1 || variants.pageInfo.hasNextPage) {
    throw new Error("Please choose an option on the product page before adding it.");
  }
  if (!variants.nodes[0].availableForSale) throw new Error(`${data.product.title} is sold out.`);
  return variants.nodes[0].id;
}

async function addVariant(merchandiseId) {
  await refreshCart();
  const lines = [{ merchandiseId, quantity: 1 }];
  if (cart) await mutate("cartLinesAdd", "$cartId: ID!, $lines: [CartLineInput!]!", "cartId: $cartId, lines: $lines", { cartId: cart.id, lines });
  else await mutate("cartCreate", "$input: CartInput", "input: $input", { input: { lines } });
  await refreshShippingSettings();
}

async function buyFromButton(button) {
  quickBuying.add(button);
  const oldBusy = button.getAttribute("aria-busy");
  const oldDisabled = button.getAttribute("aria-disabled");
  button.setAttribute("aria-busy", "true");
  button.setAttribute("aria-disabled", "true");
  openCart();
  try {
    await run(async () => {
      status.textContent = "Adding to your cart...";
      await addVariant(await resolveVariant(quickBuyReference(button)));
    });
  } finally {
    quickBuying.delete(button);
    for (const [name, value] of [["aria-busy", oldBusy], ["aria-disabled", oldDisabled]]) {
      if (value === null) button.removeAttribute(name);
      else button.setAttribute(name, value);
    }
  }
}
