const COOKIE_NAME = "other_promo_dismissed";

export function initPromoPopup() {
  const style = document.createElement("style");
  style.textContent = `
    html:not(.promo-visible) .promo_pop_up { display: none !important; }
    html.promo-visible .promo_pop_up { display: block !important; animation: promo-fade-in 200ms ease-out both; }
    @keyframes promo-fade-in { from { opacity: 0; } to { opacity: 1; } }
    @media (prefers-reduced-motion: reduce) {
      html.promo-visible .promo_pop_up { animation: none; }
    }
  `;
  document.head.appendChild(style);

  let dismissed = document.cookie.split(";").some((cookie) => cookie.trim() === `${COOKIE_NAME}=yes`);
  let timer = null;
  const classes = document.documentElement.classList;
  classes.remove("promo-visible");

  function schedule() {
    if (dismissed || timer !== null || classes.contains("promo-visible") || !classes.contains("age-confirmed")) return;
    timer = window.setTimeout(() => {
      timer = null;
      if (!dismissed && classes.contains("age-confirmed")) classes.add("promo-visible");
    }, 10000);
  }

  document.addEventListener("age-confirmed", schedule);
  document.addEventListener("click", (event) => {
    if (!event.target.closest?.("[data-close-promo]")) return;
    event.preventDefault();
    dismissed = true;
    window.clearTimeout(timer);
    timer = null;
    document.cookie = `${COOKIE_NAME}=yes; Path=/; SameSite=Lax${location.protocol === "https:" ? "; Secure" : ""}`;
    classes.remove("promo-visible");
  });
  schedule();
}
