export function initFormSubmitReveal(root) {
  const cleanups = [];
  root.querySelectorAll("form").forEach((form) => {
    const fields = [...form.querySelectorAll(".m_field")];
    const submit = form.querySelector('.submit[type="submit"]');
    if (!fields.length || !submit) return;

    const originalDisplay = submit.style.getPropertyValue("display");
    const originalPriority = submit.style.getPropertyPriority("display");
    const update = () => {
      submit.style.setProperty("display", fields.some((field) => field.value.trim()) ? "block" : "none", "important");
    };
    let resetFrame;
    const reset = () => { resetFrame = requestAnimationFrame(update); };
    form.addEventListener("input", update);
    form.addEventListener("change", update);
    form.addEventListener("focusin", update);
    form.addEventListener("reset", reset);
    update();
    cleanups.push(() => {
      cancelAnimationFrame(resetFrame);
      form.removeEventListener("input", update);
      form.removeEventListener("change", update);
      form.removeEventListener("focusin", update);
      form.removeEventListener("reset", reset);
      if (originalDisplay) submit.style.setProperty("display", originalDisplay, originalPriority);
      else submit.style.removeProperty("display");
    });
  });
  return () => cleanups.forEach((cleanup) => cleanup());
}

export function initMobileRegister(root) {
  const button = root.querySelector(".mob_reg");
  const panel = root.querySelector(".mob_reg_form");
  if (!button || !panel) return () => {};

  const mobile = window.matchMedia("(width < 991px)");
  const saved = [button, panel].map((element) => ({
    element,
    display: element.style.getPropertyValue("display"),
    priority: element.style.getPropertyPriority("display"),
  }));
  const restore = (entry) => {
    if (entry.display) entry.element.style.setProperty("display", entry.display, entry.priority);
    else entry.element.style.removeProperty("display");
  };
  let open = false;
  const close = () => {
    open = false;
    restore(saved[0]);
    if (mobile.matches) panel.style.setProperty("display", "none", "important");
    else restore(saved[1]);
  };
  const show = (event) => {
    if (!mobile.matches) return;
    event.preventDefault();
    open = true;
    button.style.setProperty("display", "none", "important");
    panel.style.setProperty("display", "flex", "important");
  };
  const outside = (event) => {
    if (open && !panel.contains(event.target) && !button.contains(event.target)) close();
  };
  button.addEventListener("click", show);
  document.addEventListener("pointerdown", outside, true);
  mobile.addEventListener("change", close);
  close();
  return () => {
    button.removeEventListener("click", show);
    document.removeEventListener("pointerdown", outside, true);
    mobile.removeEventListener("change", close);
    saved.forEach(restore);
  };
}
