export function initProductHover(root) {
  if (!document.getElementById("product-quick-add-styles")) {
    const style = document.createElement("style");
    style.id = "product-quick-add-styles";
    style.textContent = `
      .featured_item .quick_buy_btn.listing {
        display: flex;
        opacity: 0;
        pointer-events: none;
        transition: opacity 160ms ease;
      }
      .featured_item.is-quick-add-hovered .quick_buy_btn.listing,
      .featured_item:focus-within .quick_buy_btn.listing {
        opacity: 1;
        pointer-events: auto;
      }
      @media (hover: none) {
        .featured_item .quick_buy_btn.listing { opacity: 1; pointer-events: auto; }
      }
      @media (prefers-reduced-motion: reduce) {
        .featured_item .quick_buy_btn.listing { transition: none; }
      }
    `;
    document.head.append(style);
  }
  const quickAddCards = [...root.querySelectorAll(".featured_item")]
    .filter((card) => card.querySelector(".quick_buy_btn.listing"));
  let hoveredCard = null;
  let pointer = null;
  const setHoveredCard = (card) => {
    if (card === hoveredCard) return;
    hoveredCard?.classList.remove("is-quick-add-hovered");
    hoveredCard = card;
    hoveredCard?.classList.add("is-quick-add-hovered");
  };
  const updateQuickAdd = () => {
    if (!pointer) return;
    const elements = document.elementsFromPoint(pointer.x, pointer.y)
      .filter((element) => !element.closest(".floating_menu_holder"));
    const card = elements
      .map((element) => element.closest(".featured_item"))
      .find((element) => quickAddCards.includes(element));
    setHoveredCard(card || null);
    const gallery = entries.find((entry) => {
      const rect = entry.list.getBoundingClientRect();
      return pointer.x >= rect.left && pointer.x < rect.right && pointer.y >= rect.top && pointer.y < rect.bottom
        && elements.some((element) => element === entry.card || entry.card.contains(element));
    });
    move(gallery || null);
  };
  const onPointerMove = (event) => {
    if (event.pointerType === "touch") return;
    pointer = { x: event.clientX, y: event.clientY };
    updateQuickAdd();
  };
  const clearPointer = () => { pointer = null; setHoveredCard(null); stop(); };
  document.addEventListener("pointermove", onPointerMove, { passive: true });
  document.documentElement.addEventListener("pointerleave", clearPointer);
  window.addEventListener("blur", clearPointer);
  window.addEventListener("scroll", updateQuickAdd, { passive: true });
  const entries = [...root.querySelectorAll(".featured_item .slider_holder")].map((list) => {
    const card = list.closest(".featured_item");
    const slides = [...(list?.querySelectorAll(":scope > .feature_image_slider_holder") || [])];
    return { card, list, slides, styles: slides.map((slide) => slide.getAttribute("style")), listStyle: list?.getAttribute("style") };
  }).filter((entry) => entry.slides.length > 1);
  let active = null;
  let timer = 0;
  let index = 0;
  const show = (entry, selected) => entry.slides.forEach((slide, i) => {
    slide.style.visibility = i === selected ? "visible" : "hidden";
  });
  entries.forEach((entry) => {
    entry.list.style.display = "grid";
    entry.slides.forEach((slide) => {
      slide.style.gridArea = "1 / 1";
      slide.querySelectorAll("img").forEach((image) => { image.loading = "eager"; });
    });
    show(entry, 0);
  });
  const stop = () => {
    clearInterval(timer);
    timer = 0;
    if (active) show(active, 0);
    active = null;
  };
  const move = (next) => {
    if (next === active) return;
    stop();
    if (!next) return;
    active = next;
    index = 0;
    timer = window.setInterval(() => {
      if (document.hidden || !active) return;
      const nextIndex = (index + 1) % active.slides.length;
      const image = active.slides[nextIndex].querySelector("img");
      if (image && (!image.complete || !image.naturalWidth)) return;
      index = nextIndex;
      show(active, index);
    }, 500);
  };
  return () => {
    clearPointer();
    document.removeEventListener("pointermove", onPointerMove);
    document.documentElement.removeEventListener("pointerleave", clearPointer);
    window.removeEventListener("blur", clearPointer);
    window.removeEventListener("scroll", updateQuickAdd);
    stop();
    entries.forEach((entry) => {
      if (entry.listStyle === null) entry.list.removeAttribute("style");
      else entry.list.setAttribute("style", entry.listStyle);
      entry.slides.forEach((slide, i) => {
        if (entry.styles[i] === null) slide.removeAttribute("style");
        else slide.setAttribute("style", entry.styles[i]);
      });
    });
  };
}
