const normalise = (value) => value.trim().toLowerCase().normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "").replace(/[\s-]+/g, "-");

export function initProductFilters(root) {
  const list = root.querySelector("[data-filter-list]");
  const bar = root.querySelector(".filterbar");
  if (!list || !bar) return () => {};

  const selected = { country: "", type: "" };
  const pageFilter = normalise(root.dataset.filter || "");
  const restores = [];
  function remember(element, attributes) {
    const original = attributes.map((name) => [name, element.getAttribute(name)]);
    restores.push(() => original.forEach(([name, value]) => {
      if (value === null) element.removeAttribute(name);
      else element.setAttribute(name, value);
    }));
  }
  const products = [...list.children].map((element) => {
    remember(element, ["style", "hidden"]);
    const values = (kind) => [...element.querySelectorAll(`[data-${kind}-filter-text]`)]
      .map((item) => normalise(item.getAttribute(`data-${kind}-filter-text`) || item.textContent));
    return { element, display: element.style.display, country: values("country"), type: values("type") };
  });

  const groups = [...bar.querySelectorAll("[data-filter-btn]")].flatMap((button) => {
    const dropdown = button.parentElement.querySelector("[data-filter-dropdown]");
    if (!dropdown) return [];
    const kind = dropdown.querySelector("[data-filter-country]") || dropdown.classList.contains("country") ? "country" : "type";
    remember(button, ["aria-expanded"]);
    remember(dropdown, ["style", "hidden"]);
    const display = getComputedStyle(dropdown).display;
    const label = button.textContent;
    restores.push(() => { button.textContent = label; });
    const options = [...dropdown.querySelectorAll("a, button")].map((link) => {
      const source = link.matches(`[data-filter-${kind}]`) ? link : link.querySelector(`[data-filter-${kind}]`);
      const text = (source?.getAttribute(`data-filter-${kind}`) || source?.textContent || link.textContent.replace(/[()]/g, "")).trim();
      remember(link, ["aria-current"]);
      return { link, text, value: normalise(text) };
    });
    return [{ button, dropdown, kind, options, label, display: display === "none" ? "block" : display }];
  });

  function setOpen(group, open) {
    group.button.setAttribute("aria-expanded", String(open));
    group.dropdown.hidden = !open;
    group.dropdown.style.setProperty("display", open ? group.display : "none", "important");
  }
  function closeAll() { groups.forEach((group) => setOpen(group, false)); }
  function apply() {
    products.forEach((product) => {
      const matchesPage = !pageFilter || pageFilter === "all-wine"
        || product.country.includes(pageFilter) || product.type.includes(pageFilter);
      const visible = matchesPage && Object.entries(selected).every(([kind, value]) => !value || product[kind].includes(value));
      product.element.hidden = !visible;
      if (!visible) product.element.style.setProperty("display", "none", "important");
      else if (product.display) product.element.style.display = product.display;
      else product.element.style.removeProperty("display");
    });
    groups.forEach((group) => {
      const active = group.options.find((option) => option.value === selected[group.kind]);
      group.button.textContent = active ? `(${active.text})` : group.label;
      group.options.forEach((option) => {
        if (option === active) option.link.setAttribute("aria-current", "true");
        else option.link.removeAttribute("aria-current");
      });
    });
    window.ScrollTrigger?.refresh();
    window.dispatchEvent(new Event("scroll"));
  }
  function click(event) {
    const target = event.target;
    for (const group of groups) {
      if (group.button.contains(target)) {
        event.preventDefault();
        const open = group.button.getAttribute("aria-expanded") !== "true";
        closeAll();
        setOpen(group, open);
        return;
      }
      const option = group.options.find(({ link }) => link.contains(target));
      if (option) {
        event.preventDefault();
        selected[group.kind] = selected[group.kind] === option.value ? "" : option.value;
        closeAll();
        apply();
        return;
      }
    }
    const reset = target.closest("[data-filter-reset], a, button");
    if (reset && bar.contains(reset) && (reset.hasAttribute("data-filter-reset") || normalise(reset.textContent.replace(/[()]/g, "")) === "reset")) {
      event.preventDefault();
      selected.country = selected.type = "";
      closeAll();
      apply();
    } else if (!groups.some(({ dropdown }) => dropdown.contains(target))) closeAll();
  }
  function keydown(event) {
    if (event.key !== "Escape") return;
    const open = groups.find(({ button }) => button.getAttribute("aria-expanded") === "true");
    closeAll();
    open?.button.focus();
  }
  closeAll();
  if (pageFilter) apply();
  document.addEventListener("click", click);
  document.addEventListener("keydown", keydown);
  return () => {
    document.removeEventListener("click", click);
    document.removeEventListener("keydown", keydown);
    restores.reverse().forEach((restore) => restore());
  };
}
